const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const boston = ee.Geometry.Point([-71.06, 42.36]);
  const startDate = '2019-01-29';
  const endDate = '2019-02-06'; // Inclusive of Feb 5

  // 2. Data Acquisition
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(boston)
    .select('temperature_2m');

  const collectionSize = era5.size().getInfo();
  console.log(`Total hourly images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No ERA5-Land data found for the period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Process daily maximum temperatures
  // Convert from Kelvin to Celsius and get daily max
  const dailyMaxTemps = [];
  const days = ['2019-01-29', '2019-01-30', '2019-01-31', '2019-02-01', '2019-02-02', '2019-02-03', '2019-02-04', '2019-02-05'];

  for (let day of days) {
    const nextDay = ee.Date(day).advance(1, 'day').format('YYYY-MM-dd').getInfo();
    const dayCol = era5.filterDate(day, nextDay);

    const daySize = dayCol.size().getInfo();
    if (daySize === 0) {
      console.log(`No data for ${day}`);
      continue;
    }

    // Get max temperature for the day
    const maxImg = dayCol.max();
    const maxTemp = maxImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: boston,
      scale: 11132,
      maxPixels: 1e9
    }).get('temperature_2m').getInfo();

    if (maxTemp === null || maxTemp === undefined) {
      console.log(`Failed to get temperature for ${day}`);
      continue;
    }

    const maxTempC = maxTemp - 273.15;
    dailyMaxTemps.push(maxTempC);
    console.log(`${day}: Max temp = ${maxTempC.toFixed(2)}°C`);
  }

  // 4. Validation & Calculation
  if (dailyMaxTemps.length === 0) {
    console.log('No valid temperature data extracted.');
    console.log('<answer>C3</answer>');
    return;
  }

  const highestMax = Math.max(...dailyMaxTemps);
  const lowestMax = Math.min(...dailyMaxTemps);
  const difference = highestMax - lowestMax;

  console.log(`\nHighest daily max: ${highestMax.toFixed(2)}°C`);
  console.log(`Lowest daily max: ${lowestMax.toFixed(2)}°C`);
  console.log(`Difference: ${difference.toFixed(2)}°C`);

  // 5. Final Answer
  if (difference >= 22.0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
